use crate::{
    network::{
        context::State,
        payload::{
            Payload,
            play::server::{
                chunk_data_and_update_light::{
                    ChunkData, ChunkDataAndUpdateLight, HeightMap, LightData,
                },
                game_event::GameEvent,
                login::LoginPlay,
                synchronize_player_position::SynchronizePlayerPosition,
            },
        },
        protocol::{InnerProtocol, action::Action},
    },
    utils::varint::VarInt,
};
use zr_protocol::message::size::PrefixSize;

#[derive(Default, Clone)]
pub struct ConfigProtocol;

impl InnerProtocol for ConfigProtocol {
    fn handle_message(&self, payload: Payload) -> std::sync::Arc<[Action]> {
        match payload {
            Payload::AcknowledgeFinishConfiguration(_) => [
                Action::Log("🎮 Change to play state".into()),
                Action::UpdateState(State::Play),
                Action::SendMessage(Payload::LoginPlay(LoginPlay::default())),
                Action::Log("🎮 Send login play".into()),
                Action::SendBundle(
                    [
                        Payload::SynchronizePlayerPosition(SynchronizePlayerPosition {
                            teleport_id: VarInt::new(0), // TODO : teleportation buffer maybe player api
                            position: (0f64, 100f64, 0f64),
                            velocity: (0f64, 0f64, 0f64),
                            yaw: 0f32,
                            pitch: 0f32,
                            flags: 0,
                        }),
                        Payload::GameEvent(GameEvent {
                            event: 13,
                            value: 0f32,
                        }),
                        Payload::ChunkDataAndUpdateLight(
                            hard_coded_chunk_data_and_light(), // TODO : world api
                        ),
                    ]
                    .into(),
                ),
                Action::Log("⭐ GameEvent & Chunk".into()),
            ]
            .into(),
            Payload::ServerBoundKnownPack(_) => [].into(),
            _ => [].into(),
        }
    }
}

macro_rules! hex_to_bytes {
    ($hex: tt) => {
        stringify!($hex)
            .as_bytes()
            .chunks(2)
            .map(|bytes| u8::from_str_radix(&String::from_utf8_lossy(bytes), 16).unwrap())
            .collect::<Vec<_>>()
    };
}

macro_rules! hex_to_longs {
    ($hex: tt) => {
        stringify!($hex)
            .as_bytes()
            .chunks(16)
            .map(|bytes| u64::from_str_radix(&String::from_utf8_lossy(bytes), 16).unwrap())
            .collect::<Vec<_>>()
    };
}

fn hard_coded_chunk_data_and_light() -> ChunkDataAndUpdateLight {
    let chunk_data = hex_to_bytes!
        ();
    // HEIGHTMAPS

    let world_surface = HeightMap {
        ty: VarInt::new(1),
        data: PrefixSize::new(hex_to_longs!().into()),
    };
    let motion_blocking = HeightMap {
        ty: VarInt::new(4),
        data: PrefixSize::new(hex_to_longs!().into()),
    };
    let motion_blocking_no_leaves = HeightMap {
        ty: VarInt::new(5),
        data: PrefixSize::new(hex_to_longs!().into()),
    };

    let data = ChunkData {
        heightmaps: PrefixSize::new(
            [world_surface, motion_blocking, motion_blocking_no_leaves].into(),
        ),
        data: PrefixSize::new(chunk_data.into()),
        block_entities: PrefixSize::new([].into()),
    };
    let light = LightData {
        sky_light_mask: PrefixSize::new(hex_to_longs!(0000000000000600).into()),
        block_light_mask: PrefixSize::new(hex_to_longs!(0000000000000060).into()),
        empty_sky_light_mask: PrefixSize::new(hex_to_longs!(00000000000001ff).into()),
        empty_block_light_mask: PrefixSize::new(hex_to_longs!(000000000000079f).into()),
        sky_light_arrays: PrefixSize::new([PrefixSize::new(hex_to_bytes!    ().into()),PrefixSize::new(hex_to_bytes!().into())].into()),
        block_light_arrays: PrefixSize::new([
            PrefixSize::new(hex_to_bytes!().into()),
            PrefixSize::new(hex_to_bytes!(                
).into())
        ].into()),
    };

    ChunkDataAndUpdateLight {
        x: 0,
        z: 0,
        data,
        light,
    }
}
